// Author: MiYu. Source forms and Cyclone attachment checks exercise identity, real action consumers, dispels and map ability overrides.
#include "session.h"
#include "setup.h"
#include "scene_assets.h"
#include "model.h"
#include <bit>
#include <algorithm>
#include <cfloat>
#include <cmath>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_morph_tests <data-root> <fixture> [morph|cyclone|cyclone-item|models|lifecycle]");std::wstring mode=argc>3?argv[3]:L"morph";if(mode!=L"morph" && mode!=L"cyclone" && mode!=L"cyclone-item" && mode!=L"models" && mode!=L"lifecycle")throw std::runtime_error("Unknown morph mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto type=[&](const char* code){return vm.integer(int(ObjectData::code(code)));};auto real=[&](float value){return vm.real(jass::Real::fromBits(std::bit_cast<std::uint32_t>(value)));};auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto hexer=vm.global("hexer"),sorceress=vm.global("sorceress"),talon=vm.global("talon"),purger=vm.global("purger"),ground=vm.global("groundUnit"),air=vm.global("airUnit"),victim=vm.global("cycloneUnit");auto g=session.units().at(ground.bits),a=session.units().at(air.bits),v=session.units().at(victim.bits);auto cast=[&](jass::Value caster,const char* ability,const char* order,jass::Value target){auto remaining=session.spellCooldown(caster.bits,ObjectData::code(ability));if(remaining>0)session.advance(remaining+1./32);if(!call("IssueTargetOrder",{caster,vm.string(order),target}).bits)throw std::runtime_error(std::string("Source order rejected: ")+order);};
        if(mode==L"models"){
            SceneAssets assets(session.world()->resources());Log log(std::filesystem::path(argv[2]).parent_path()/L"models-import.log");ObjectData data(session.world()->resources());unsigned imported=0;for(auto code:{"nshe","nshf","nsha","nshw","npig","nalb","nsea"}){auto path=data.field(ObjectData::code(code),"UnitUI","file");auto& model=assets.model(path,log);require(model.radius()>0 && model.sequence("Stand"),"Source creature model did not import");++imported;}auto& carrier=assets.model("Abilities\\Spells\\NightElf\\Cyclone\\CycloneTarget.mdl",log);require(carrier.hasAttachment("sprite,first") && carrier.sequence("Stand"),"Source Cyclone carrier attachment is missing");D3DMATRIX identity{};identity._11=identity._22=identity._33=identity._44=1;float maximum=-FLT_MAX;for(auto elapsed:{0ull,500ull,1500ull}){auto pose=carrier.attachment("sprite,first",identity,elapsed,identity);require(pose && std::isfinite(pose->_41) && std::isfinite(pose->_42) && std::isfinite(pose->_43),"Cyclone source attachment produced no finite pose");maximum=std::max(maximum,pose->_43);std::cout<<"carrier_pose_ms="<<elapsed<<" z="<<pose->_43<<'\n';}require(maximum>1,"Cyclone source attachment did not lift its carried unit");std::cout<<"PASS original_form_models="<<imported<<" cyclone_attachment_pose GPU=pending\n";
        }else if(mode==L"morph"){
            auto item=call("UnitAddItemById",{ground,type("phea")});require(item.bits!=0,"Original inventory fixture failed");call("SetWidgetLife",{ground,real(150)});session.advance(.5);require(g->aura.armor>0,"Source Devotion aura did not enter the fixture");auto originalModel=g->model;cast(hexer,"AOhx","hex",ground);session.advance(1.2);require(g->morphed() && g->displayModel()!=originalModel && g->model==originalModel && call("GetUnitTypeId",{ground}).bits==ObjectData::code("hfoo") && call("IsUnitType",{ground,vm.handle("unittype",22)}).bits,"Hex lost real temporary appearance or original identity");require(number(g->currentMoveSpeed())==100 && !session.attackUnit(ground.bits,hexer.bits) && !session.castSpell(ground.bits,ObjectData::code("AHwe")) && !call("UnitUseItem",{ground,item}).bits,"Hex did not suppress original attacks, spells and item use");float before=number(g->x);require(call("IssuePointOrder",{ground,vm.string("move"),real(256),real(0)}).bits,"Morphed unit could not move");session.advance(.5);require(number(g->x)>before+25,"Morphed source movement speed was not consumed");call("SetUnitMoveSpeed",{ground,real(245)});require(number(g->currentMoveSpeed())==100,"Native base speed overwrote the active creature form");session.advance(3.5);require(g->aura.armor==0,"Morphed source still bestowed its aura with source flag disabled");cast(purger,"Apg2","purge",ground);session.advance(1.6);require(!g->morphed() && g->displayModel()==originalModel && number(g->currentMoveSpeed())==245 && session.items().at(item.bits)->holder==ground.bits && g->inventory[0]==item.bits,"Morph dispel did not restore source state while preserving native writes and inventory");cast(sorceress,"Aply","polymorph",air);session.advance(1.5);require(a->morphed() && a->morphAppearance()->type==ObjectData::code("nshf") && a->airborne(),"Polymorph did not select the original flying sheep");auto hero=call("CreateUnit",{call("Player",{vm.integer(1)}),type("Hpal"),real(128),real(256),real(0)});session.advance(session.spellCooldown(sorceress.bits,ObjectData::code("Aply"))+1./32);require(!session.castSpell(sorceress.bits,ObjectData::code("Aply"),hero.bits),"Source Polymorph accepted a hero");std::cout<<"PASS hex_identity_actions_inventory_speed_aura_and_flying_polymorph\n";
        }else if(mode==L"cyclone-item"){
            auto wand=call("UnitAddItemById",{hexer,type("wcyc")});require(wand.bits && session.itemNeedsTarget(wand.bits),"Cyclone wand did not expose a unit target");require(call("UnitUseItemTarget",{hexer,wand,victim}).bits,"Cyclone wand target order was rejected");session.advance(1.2);require(v->cycloned() && v->stunned() && session.items().contains(wand.bits) && session.items().at(wand.bits)->charges==2,"Cyclone wand did not consume a charge and apply the real control state");std::cout<<"PASS cyclone_wand_target_charge_and_control\n";
        }else if(mode==L"cyclone"){
            cast(talon,"Acyc","cyclone",victim);session.advance(1.2);require(v->cycloned() && v->stunned() && v->cyclone()->dispellable && !v->cyclone()->visuals.empty(),"Cyclone did not create its real control and carrier effect");auto effect=session.effects().at(v->cyclone()->visuals.back());require(effect->groundAnchor && effect->target==victim.bits && !effect->attachment.size(),"Cyclone carrier was attached recursively to its carried unit");require(!session.damageUnit(purger.bits,victim.bits,40,0,26) && !session.castSpell(victim.bits,ObjectData::code("AHwe")) && !call("IssuePointOrder",{victim,vm.string("move"),real(256),real(-256)}).bits,"Cyclone did not reject actual damage and commands");cast(purger,"Apg2","purge",victim);session.advance(1.6);require(!v->cycloned(),"Source dispellable Cyclone was not removed by Purge");call("UnitRemoveAbility",{talon,type("Acyc")});call("UnitAddAbility",{talon,type("C000")});require(!session.spellInfo(ObjectData::code("C000"),1).dispellable,"Map cyc1 override was not consumed");cast(talon,"C000","cyclone",victim);session.advance(1.2);cast(purger,"Apg2","purge",victim);session.advance(1.6);require(v->cycloned() && !v->cyclone()->dispellable,"Non-dispellable map Cyclone was removed by Purge");call("UnitRemoveBuffs",{victim,vm.boolean(false),vm.boolean(true)});require(v->cycloned(),"Generic buff removal ignored source Cyclone dispel protection");session.advance(20.5);require(!v->cycloned() && !v->stunned() && call("GetUnitTypeId",{victim}).bits==ObjectData::code("hfoo"),"Cyclone expiry did not restore the original unit");std::cout<<"PASS cyclone_controls_carrier_dispels_map_override_and_expiry\n";
        }else{
            cast(hexer,"AOhx","hex",ground);session.advance(1.2);call("SetUnitOwner",{ground,call("Player",{vm.integer(0)}),vm.boolean(true)});call("RemoveUnit",{hexer});session.advance(15.5);require(!g->morphed() && g->owner==0 && g->type==ObjectData::code("hfoo"),"Morph caster removal or ownership transfer lost original state");cast(talon,"Acyc","cyclone",victim);session.advance(1.2);call("KillUnit",{victim});require(!v->cycloned() && number(v->life)==0,"Cyclone death did not clear real control state");std::cout<<"PASS morph_owner_caster_removal_expiry_and_cyclone_death\n";
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
